{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260926T221158Z/cell-B0ad6y/src/nodes.js","content":"/**
 * Value node shapes shared by the parser and the two output formats.
 *
 * A table (and an inline table) is `{ kind: 'table', entries, headerDefined }`
 * where `entries` is a null-prototype object mapping a decoded key to another
 * node, and `headerDefined` tracks whether a `[name]` header has already made
 * this exact table current (used to reject a second one). An array of tables
 * is `{ kind: 'array-of-tables', items }` holding table nodes in append order.
 * A plain array is `{ kind: 'array', items }` holding any value node. Scalars
 * are `{ kind, value }` with kind one of `string`, `integer`, `float`,
 * `boolean`; `integer` values are `BigInt`, `float` values are `Number`.
 */

export function makeTable() {
  return { kind: 'table', entries: Object.create(null), headerDefined: false }
}

/** Joins a path prefix (possibly empty) with further dotted-name parts. */
export function joinPath(prefix, parts) {
  const joined = parts.join('.')
  return prefix === '' ? joined : `${prefix}.${joined}`
}
"}

