import { makeTable, joinPath } from './nodes.js'
import { resolveIntermediate } from './resolve.js'

const NAME_CHAR = /[A-Za-z0-9_-]/
const INT_RE = /^[+-]?\d+(?:_\d+)*$/
const FLOAT_RE = /^[+-]?\d+(?:_\d+)*(?:\.\d+(?:_\d+)*)?(?:[eE][+-]?\d+(?:_\d+)*)?$/
const WORD_STOP = new Set([' ', '\t', ',', ']', '}'])

/**
 * Parses one line's worth of syntax (a header, a `key = value` line, or a
 * value nested inside it) from a fixed position. Every directive fits on a
 * single line, so this never looks past the end of `line`.
 */
export class LineParser {
  constructor(line, lineNo) {
    this.line = line
    this.len = line.length
    this.lineNo = lineNo
    this.pos = 0
  }

  error(reason) {
    throw new ParseError(this.lineNo, reason)
  }

  skipWs() {
    while (this.pos < this.len && (this.line[this.pos] === ' ' || this.line[this.pos] === '\t')) {
      this.pos++
    }
  }

  /** Everything but spaces, tabs and a comment from here on is an error. */
  checkTrailing(reason) {
    this.skipWs()
    if (this.pos >= this.len) return
    const c = this.line[this.pos]
    if (c === '#' || c === ';') return
    this.error(reason)
  }

  parseName() {
    this.skipWs()
    if (this.pos >= this.len) this.error('expected a name')
    const c = this.line[this.pos]
    if (c === '"') return this.parseBasicString()
    if (c === "'") return this.parseLiteralString()
    if (NAME_CHAR.test(c)) {
      const start = this.pos
      while (this.pos < this.len && NAME_CHAR.test(this.line[this.pos])) this.pos++
      return this.line.slice(start, this.pos)
    }
    this.error('expected a name')
  }

  parseDottedName() {
    const parts = [this.parseName()]
    while (true) {
      this.skipWs()
      if (this.pos < this.len && this.line[this.pos] === '.') {
        this.pos++
        parts.push(this.parseName())
      } else {
        break
      }
    }
    return parts
  }

  parseBasicString() {
    this.pos++ // opening quote
    let out = ''
    while (true) {
      if (this.pos >= this.len) this.error('unterminated string')
      const c = this.line[this.pos]
      if (c === '"') {
        this.pos++
        return out
      }
      if (c === '\\') {
        this.pos++
        if (this.pos >= this.len) this.error('unterminated string')
        const e = this.line[this.pos]
        if (e === '"') {
          out += '"'
          this.pos++
        } else if (e === '\\') {
          out += '\\'
          this.pos++
        } else if (e === 'n') {
          out += '\n'
          this.pos++
        } else if (e === 't') {
          out += '\t'
          this.pos++
        } else if (e === 'r') {
          out += '\r'
          this.pos++
        } else if (e === '0') {
          out += '\0'
          this.pos++
        } else if (e === 'u') {
          const hex = this.line.slice(this.pos + 1, this.pos + 5)
          if (hex.length === 4 && /^[0-9a-fA-F]{4}$/.test(hex)) {
            out += String.fromCharCode(parseInt(hex, 16))
            this.pos += 5
          } else {
            this.error('invalid escape \\u')
          }
        } else {
          this.error(`invalid escape \\${e}`)
        }
      } else {
        out += c
        this.pos++
      }
    }
  }

  parseLiteralString() {
    this.pos++ // opening quote
    const start = this.pos
    while (true) {
      if (this.pos >= this.len) this.error('unterminated string')
      if (this.line[this.pos] === "'") {
        const s = this.line.slice(start, this.pos)
        this.pos++
        return s
      }
      this.pos++
    }
  }

  wordToValueNode(word) {
    if (word === 'true') return { kind: 'boolean', value: true }
    if (word === 'false') return { kind: 'boolean', value: false }
    if (INT_RE.test(word)) {
      const cleaned = word.replace(/_/g, '').replace(/^\+/, '')
      return { kind: 'integer', value: BigInt(cleaned) }
    }
    if (FLOAT_RE.test(word) && /[.eE]/.test(word)) {
      const cleaned = word.replace(/_/g, '')
      return { kind: 'float', value: Number(cleaned) }
    }
    this.error(`invalid value ${word}`)
  }

  /**
   * `prefix` is the root-relative dotted path this value will end up at,
   * used only to build the paths in errors raised by nested inline tables.
   */
  parseValue(prefix) {
    this.skipWs()
    if (this.pos >= this.len) this.error('expected a value')
    const c = this.line[this.pos]
    if (c === '"') return { kind: 'string', value: this.parseBasicString() }
    if (c === "'") return { kind: 'string', value: this.parseLiteralString() }
    if (c === '[') return this.parseArray(prefix)
    if (c === '{') return this.parseInlineTable(prefix)
    if (c === ',' || c === ']' || c === '}') this.error('expected a value')
    const start = this.pos
    while (this.pos < this.len && !WORD_STOP.has(this.line[this.pos])) this.pos++
    const word = this.line.slice(start, this.pos)
    return this.wordToValueNode(word)
  }

  parseArray(prefix) {
    this.pos++ // '['
    const items = []
    this.skipWs()
    if (this.pos < this.len && this.line[this.pos] === ']') {
      this.pos++
      return { kind: 'array', items }
    }
    while (true) {
      if (this.pos >= this.len) this.error('unterminated array')
      items.push(this.parseValue(prefix))
      this.skipWs()
      if (this.pos >= this.len) this.error('unterminated array')
      const c = this.line[this.pos]
      if (c === ']') {
        this.pos++
        break
      } else if (c === ',') {
        this.pos++
        this.skipWs()
        if (this.pos < this.len && this.line[this.pos] === ']') {
          this.pos++
          break
        }
      } else {
        this.error('trailing text after a value')
      }
    }
    return { kind: 'array', items }
  }

  parseInlineTable(prefix) {
    this.pos++ // '{'
    const table = makeTable()
    this.skipWs()
    if (this.pos < this.len && this.line[this.pos] === '}') {
      this.pos++
      return table
    }
    while (true) {
      if (this.pos >= this.len) this.error('unterminated inline table')
      const parts = this.parseDottedName()
      this.skipWs()
      if (this.pos >= this.len) this.error('unterminated inline table')
      if (this.line[this.pos] !== '=') this.error('expected = in an inline table')
      this.pos++
      const childPath = joinPath(prefix, parts)
      const value = this.parseValue(childPath)
      const parentParts = parts.slice(0, -1)
      const lastName = parts[parts.length - 1]
      const parent = resolveIntermediate(table, parentParts, prefix, this.lineNo)
      if (Object.prototype.hasOwnProperty.call(parent.entries, lastName)) {
        this.error(`key ${childPath} is defined twice`)
      }
      parent.entries[lastName] = value
      this.skipWs()
      if (this.pos >= this.len) this.error('unterminated inline table')
      const c = this.line[this.pos]
      if (c === '}') {
        this.pos++
        break
      } else if (c === ',') {
        this.pos++
        this.skipWs()
      } else {
        this.error('trailing text after a value')
      }
    }
    return table
  }
}
