  if (isArray) {
    const parentParts = parts.slice(0, -1)
    const lastName = parts[parts.length - 1]
    const parent = resolveIntermediate(root, parentParts, '', lineNo)
    let existing = parent.entries[lastName]
    if (existing === undefined) {
