 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */

import { parseDocument } from './parser.js'
import { toJSON, toKeys } from './format.js'
import { ParseError } from './errors.js'

function readStdin() {
  return new Promise((resolve, reject) => {
    const chunks = []
    process.stdin.on('data', (c) => chunks.push(c))
    process.stdin.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')))
    process.stdin.on('error', reject)
  })
}

async function main() {
  const mode = process.argv[2]
  if (mode !== 'json' && mode !== 'keys') {
    process.stderr.write('error: usage: cli.js json|keys\n')
    process.exit(2)
    return
  }

  const input = await readStdin()
  let root
  try {
    root = parseDocument(input)
  } catch (e) {
    if (e instanceof ParseError) {
      process.stderr.write(`error: line ${e.line}: ${e.reason}\n`)
      process.exit(2)
      return
    }
    throw e
  }

  if (mode === 'json') {
    process.stdout.write(`${toJSON(root)}\n`)
  } else {
    process.stdout.write(toKeys(root))
  }
  process.exit(0)
}

main()
